package com.moodcanvas.dao;
import com.moodcanvas.model.MoodEntry;import com.moodcanvas.util.DBConnection;import java.sql.*;import java.util.*;
public class MoodDAO {public void saveMood(int u,String t,String g)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO mood_entries(userID,moodText,moodTag) VALUES(?,?,?)")){p.setInt(1,u);p.setString(2,t);p.setString(3,g);p.executeUpdate();}}public List<MoodEntry> getAll()throws SQLException{List<MoodEntry>a=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM mood_entries ORDER BY submittedAt DESC");ResultSet r=p.executeQuery()){while(r.next())a.add(new MoodEntry(r.getInt("moodID"),r.getInt("userID"),r.getString("moodText"),r.getString("moodTag"),r.getTimestamp("submittedAt")));}return a;}public int count()throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT COUNT(*) FROM mood_entries");ResultSet r=p.executeQuery()){r.next();return r.getInt(1);}}}
